WITH unpacked AS (SELECT id, service, host, level, latency_ms, status_code, payload_json, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').user.tier AS tier, COALESCE(context['region'], 'unknown') AS region_or_default, CAST((status_code & 8) != 0 AS INT) AS flag_bit8, GET_JSON_OBJECT(payload_json, '$.user.tier') AS user_tier, GET_JSON_OBJECT(payload_json, '$.duration') AS duration_text FROM app_logs) SELECT id, service, host, level, region_or_default, LEAD(flag_bit8, 2, 0) OVER (PARTITION BY host ORDER BY flag_bit8, id) AS next_flag_bit8, LAST_VALUE(latency_ms) IGNORE NULLS OVER (PARTITION BY tier ORDER BY status_code, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_latency_ms FROM unpacked WHERE host IN ('h1', 'h4', 'h3')
